206	void DataPartStorageOnDisk::remove(
207	    CanRemoveCallback && can_remove_callback,
208	    const MergeTreeDataPartChecksums & checksums,
209	    std::list<ProjectionChecksums> projections,
210	    Poco::Logger * log)
211	{
212	    /// NOTE We rename part to delete_tmp_<relative_path> instead of delete_tmp_<name> to avoid race condition
213	    /// when we try to remove two parts with the same name, but different relative paths,
214	    /// for example all_1_2_1 (in Deleting state) and tmp_merge_all_1_2_1 (in Temporary state).
215	    fs::path from = fs::path(root_path) / part_dir;
216	    // fs::path to = fs::path(root_path) / ("delete_tmp_" + part_dir);
217	    // TODO directory delete_tmp_<name> is never removed if server crashes before returning from this function
218	
219	    /// Cut last "/" if it exists (it shouldn't). Otherwise fs::path behave differently.
220	    fs::path part_dir_without_slash = part_dir.ends_with("/") ? part_dir.substr(0, part_dir.size() - 1) : part_dir;
221	
222	    /// NOTE relative_path can contain not only part name itself, but also some prefix like
223	    /// "moving/all_1_1_1" or "detached/all_2_3_5". We should handle this case more properly.
224	    if (part_dir_without_slash.has_parent_path())
225	    {
226	        auto parent_path = part_dir_without_slash.parent_path();
227	        if (parent_path == "detached")
228	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Trying to remove detached part {} with path {} in remove function. It shouldn't happen", part_dir, root_path);
229	
230	        part_dir_without_slash = parent_path / ("delete_tmp_" + std::string{part_dir_without_slash.filename()});
231	    }
232	    else
233	    {
234	        part_dir_without_slash = ("delete_tmp_" + std::string{part_dir_without_slash.filename()});
235	    }
236	
237	    fs::path to = fs::path(root_path) / part_dir_without_slash;
238	
239	    std::optional<CanRemoveDescription> can_remove_description;
240	
241	    auto disk = volume->getDisk();
242	    if (disk->exists(to))
243	    {
244	        LOG_WARNING(log, "Directory {} (to which part must be renamed before removing) already exists. Most likely this is due to unclean restart or race condition. Removing it.", fullPath(disk, to));
245	        try
246	        {
247	            can_remove_description.emplace(can_remove_callback());
248	            disk->removeSharedRecursive(fs::path(to) / "", !can_remove_description->can_remove_anything, can_remove_description->files_not_to_remove);
249	        }
250	        catch (...)
251	        {
252	            LOG_ERROR(log, "Cannot recursively remove directory {}. Exception: {}", fullPath(disk, to), getCurrentExceptionMessage(false));
253	            throw;
254	        }
255	    }
256	
257	    try
258	    {
259	        disk->moveDirectory(from, to);
260	        onRename(root_path, part_dir_without_slash);
261	    }
262	    catch (const fs::filesystem_error & e)
263	    {
264	        if (e.code() == std::errc::no_such_file_or_directory)
265	        {
266	            LOG_ERROR(log, "Directory {} (part to remove) doesn't exist or one of nested files has gone. Most likely this is due to manual removing. This should be discouraged. Ignoring.", fullPath(disk, to));
267	            return;
268	        }
269	        throw;
270	    }
271	
272	    if (!can_remove_description)
273	        can_remove_description.emplace(can_remove_callback());
274	
275	    // Record existing projection directories so we don't remove them twice
276	    std::unordered_set<String> projection_directories;
277	    std::string proj_suffix = ".proj";
278	    for (const auto & projection : projections)
279	    {
280	        std::string proj_dir_name = projection.name + proj_suffix;
281	        projection_directories.emplace(proj_dir_name);
282	
283	        clearDirectory(
284	            fs::path(to) / proj_dir_name,
285	            can_remove_description->can_remove_anything, can_remove_description->files_not_to_remove, projection.checksums, {}, log, true);
286	    }
287	
288	    /// It is possible that we are removing the part which have a written but not loaded projection.
289	    /// Such a part can appear server was restarted after DROP PROJECTION but before old part was removed.
290	    /// In this case, the old part will load only projections from metadata.
291	    /// See test 01701_clear_projection_and_part.
292	    for (const auto & [name, _] : checksums.files)
293	    {
294	        if (endsWith(name, proj_suffix) && !projection_directories.contains(name) && disk->isDirectory(fs::path(to) / name))
295	        {
296	
297	            /// If we have a directory with suffix '.proj' it is likely a projection.
298	            /// Try to load checksums for it (to avoid recursive removing fallback).
299	            std::string checksum_path = fs::path(to) / name / "checksums.txt";
300	            if (disk->exists(checksum_path))
301	            {
302	                try
303	                {
304	                    MergeTreeDataPartChecksums tmp_checksums;
305	                    auto in = disk->readFile(checksum_path, {});
306	                    tmp_checksums.read(*in);
307	
308	                    projection_directories.emplace(name);
309	
310	                    clearDirectory(
311	                        fs::path(to) / name,
312	                        can_remove_description->can_remove_anything, can_remove_description->files_not_to_remove, tmp_checksums, {}, log, true);
313	                }
314	                catch (...)
315	                {
316	                    LOG_ERROR(log, "Cannot load checksums from {}", checksum_path);
317	                }
318	            }
319	        }
320	    }
321	
322	    clearDirectory(to, can_remove_description->can_remove_anything, can_remove_description->files_not_to_remove, checksums, projection_directories, log, false);
323	}
