325	void DataPartStorageOnDisk::clearDirectory(
326	    const std::string & dir,
327	    bool can_remove_shared_data,
328	    const NameSet & names_not_to_remove,
329	    const MergeTreeDataPartChecksums & checksums,
330	    const std::unordered_set<String> & skip_directories,
331	    Poco::Logger * log,
332	    bool is_projection) const
333	{
334	    auto disk = volume->getDisk();
335	
336	    if (checksums.empty())
337	    {
338	        if (is_projection)
339	        {
340	            LOG_ERROR(
341	                log,
342	                "Cannot quickly remove directory {} by removing files; fallback to recursive removal. Reason: checksums.txt is missing",
343	                fullPath(disk, dir));
344	        }
345	
346	        /// If the part is not completely written, we cannot use fast path by listing files.
347	        disk->removeSharedRecursive(fs::path(dir) / "", !can_remove_shared_data, names_not_to_remove);
348	
349	        return;
350	    }
351	
352	    try
353	    {
354	        /// Remove each expected file in directory, then remove directory itself.
355	        RemoveBatchRequest request;
356	
357	#if !defined(__clang__)
358	#    pragma GCC diagnostic push
359	#    pragma GCC diagnostic ignored "-Wunused-variable"
360	#endif
361	        for (const auto & [file, _] : checksums.files)
362	        {
363	            if (skip_directories.find(file) == skip_directories.end())
364	                request.emplace_back(fs::path(dir) / file);
365	        }
366	#if !defined(__clang__)
367	#    pragma GCC diagnostic pop
368	#endif
369	
370	        for (const auto & file : {"checksums.txt", "columns.txt"})
371	            request.emplace_back(fs::path(dir) / file);
372	
373	        request.emplace_back(fs::path(dir) / "default_compression_codec.txt", true);
374	        request.emplace_back(fs::path(dir) / "delete-on-destroy.txt", true);
375	
376	        if (!is_projection)
377	            request.emplace_back(fs::path(dir) / "txn_version.txt", true);
378	
379	        disk->removeSharedFiles(request, !can_remove_shared_data, names_not_to_remove);
380	        disk->removeDirectory(dir);
381	    }
382	    catch (...)
383	    {
384	        /// Recursive directory removal does many excessive "stat" syscalls under the hood.
385	
386	        LOG_ERROR(log, "Cannot quickly remove directory {} by removing files; fallback to recursive removal. Reason: {}", fullPath(disk, dir), getCurrentExceptionMessage(false));
387	        disk->removeSharedRecursive(fs::path(dir) / "", !can_remove_shared_data, names_not_to_remove);
388	    }
389	}
