391	std::string DataPartStorageOnDisk::getRelativePathForPrefix(Poco::Logger * log, const String & prefix, bool detached) const
392	{
393	    String res;
394	
395	    auto full_relative_path = fs::path(root_path);
396	    if (detached)
397	        full_relative_path /= "detached";
398	
399	    for (int try_no = 0; try_no < 10; ++try_no)
400	    {
401	        res = (prefix.empty() ? "" : prefix + "_") + part_dir + (try_no ? "_try" + DB::toString(try_no) : "");
402	
403	        if (!volume->getDisk()->exists(full_relative_path / res))
404	            return res;
405	
406	        LOG_WARNING(log, "Directory {} (to detach to) already exists. Will detach to directory with '_tryN' suffix.", res);
407	    }
408	
409	    return res;

