222	    /**
223	     * Part state is a stage of its lifetime. States are ordered and state of a part could be increased only.
224	     * Part state should be modified under data_parts mutex.
225	     *
226	     * Possible state transitions:
227	     * Temporary -> PreActive:       we are trying to add a fetched, inserted or merged part to active set
228	     * PreActive -> Outdated:        we could not add a part to active set and are doing a rollback (for example it is duplicated part)
229	     * PreActive -> Active:          we successfully added a part to active dataset
230	     * PreActive -> Outdated:        a part was replaced by a covering part or DROP PARTITION
231	     * Outdated -> Deleting:         a cleaner selected this part for deletion
232	     * Deleting -> Outdated:         if an ZooKeeper error occurred during the deletion, we will retry deletion
233	     * Active -> DeleteOnDestroy:    if part was moved to another disk
234	     */
235	    enum class State
236	    {
237	        Temporary,       /// the part is generating now, it is not in data_parts list
238	        PreActive,    /// the part is in data_parts, but not used for SELECTs
239	        Active,       /// active data part, used by current and upcoming SELECTs
240	        Outdated,        /// not active data part, but could be used by only current SELECTs, could be deleted after SELECTs finishes
241	        Deleting,        /// not active data part with identity refcounter, it is deleting right now by a cleaner
242	        DeleteOnDestroy, /// part was moved to another disk and should be deleted in own destructor
243	    };
